<?php if ($invoices === []): ?><div class="patient-empty-state"><i class="bi bi-receipt" aria-hidden="true"></i><strong>No invoices found</strong><span>Invoices linked to your patient account will appear here.</span></div><?php else: ?><div class="table-responsive patient-invoices-table-wrap"><table class="table patient-invoices-table"><caption class="sr-only">Patient invoices and payments</caption><thead><tr><th>Invoice</th><th>Order / prescription</th><th>Amount</th><th>Payment</th><th>Provider / reference</th><th>Date</th><th>Actions</th></tr></thead><tbody><?php foreach ($invoices as $invoice): ?><tr><td data-label="Invoice"><strong class="patient-invoice-value" title="<?= esc($invoice['invoice_number'], 'attr') ?>"><?= esc($invoice['invoice_number']) ?></strong><small class="d-block text-muted"><?= esc($invoice['invoice_date_display']) ?></small></td><td data-label="Order / prescription"><span class="patient-invoice-value" title="<?= esc($invoice['order_number'] ?? '', 'attr') ?>"><?= esc($invoice['order_number'] ?: 'Order unavailable') ?></span><small class="d-block text-muted patient-invoice-value" title="<?= esc($invoice['prescription_number'] ?? '', 'attr') ?>"><?= esc($invoice['prescription_number'] ?: 'Prescription unavailable') ?></small></td><td data-label="Amount"><strong><?= esc(($invoice['currency'] ?? 'INR') . ' ' . number_format((float) ($invoice['total'] ?? 0), 2)) ?></strong><small class="d-block text-muted">Paid <?= esc(number_format((float) $invoice['paid_amount'], 2)) ?></small></td><td data-label="Payment"><span class="badge patient-status-badge patient-status-<?= esc($invoice['payment_status']) ?>"><?= esc($invoice['payment_status_label']) ?></span></td><td data-label="Provider / reference"><span class="patient-invoice-value" title="<?= esc($invoice['payment_provider'] ?? '', 'attr') ?>"><?= esc($invoice['payment_provider'] ?: 'Not recorded') ?></span><small class="d-block text-muted patient-invoice-value" title="<?= esc($invoice['payment_reference'] ?? '', 'attr') ?>"><?= esc($invoice['payment_reference'] ?: 'No reference') ?></small></td><td data-label="Date"><small><?= esc($invoice['created_at'] ?? '—') ?></small><small class="d-block text-muted"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i><?= esc($invoice['updated_at'] ?? '—') ?></small></td><td data-label="Actions"><div class="dropdown"><button class="btn btn-sm btn-primary dropdown-toggle" type="button" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">More Actions</button><div class="dropdown-menu dropdown-menu-right"><button class="dropdown-item patient-invoice-view" type="button" data-id="<?= (int) $invoice['id'] ?>" data-toggle="modal" data-target="#patient-invoice-detail-modal">View invoice</button><button class="dropdown-item patient-invoice-print-row" type="button" data-id="<?= (int) $invoice['id'] ?>">Print invoice</button><?php if (! empty($invoice['order_id'])): ?><a class="dropdown-item" href="<?= base_url('patient/orders?order_id=' . (int) $invoice['order_id']) ?>">View linked order</a><?php endif; ?><?php if (! empty($invoice['prescription_id'])): ?><a class="dropdown-item" href="<?= base_url('patient/prescriptions?prescription_id=' . (int) $invoice['prescription_id']) ?>">View linked prescription</a><?php endif; ?></div></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
